entries[5648] = { ["name"] = "Tome of Frost Armor III", ["text"] = "Classes: Mage\nRequires Level 20\nUse: Teaches Frost Armor (Rank 3).\nIncreases Armor by 200. If an enemy strikes the caster, they may have their movement slowed by 30% and the time between their attacks increased by 25% for 5 sec. Only one type of Armor spell can be active on the Mage at any time. Lasts 30 min.\nSell Price: 7 25" }
