entries[5697] = { ["name"] = "Tablet of Healing Totem", ["text"] = "Classes: Shaman\nRequires Level 6\nUse: Teaches Healing Totem (Rank 1).\nSummons a Healing Stream Totem with 5 health at the feet of the caster for 5 min that heals group members within 30 yards for 6 every 2 seconds.\nSell Price: 50" }
entries[5698] = { ["name"] = "Tablet of Lightning Shield", ["text"] = "Classes: Shaman\nRequires Level 8\nUse: Teaches Lightning Shield (Rank 1).\nThe caster is surrounded by 3 balls of lightning. When a spell, melee or ranged attack hits the caster, the attacker will be struck for 13 Nature damage. This expends one lightning ball. Only one ball will fire every few seconds. Lasts 10 min. Only one Elemental Shield can be active on the Shaman at any one time. (3.5s cooldown)\nSell Price: 50" }
entries[5699] = { ["name"] = "Tablet of Ghost Wolf", ["text"] = "Classes: Shaman\nRequires Level 12\nUse: Teaches Ghost Wolf (Rank 1).\nTurns the Shaman into a Ghost Wolf, increasing speed by 40%\n\nGlyph of Ghost Wolf\nand regenerating 1% of your maximum health every 5 sec\n\nAs a Ghost Wolf, the Shaman is less hindered by effects that would reduce movement speed. Only useable outdoors.\nSell Price: 2 50" }
entries[5700] = { ["name"] = "Tablet of Healing Totem II", ["text"] = "Classes: Shaman\nRequires Level 12\nUse: Teaches Healing Totem (Rank 2).\nSummons a Healing Stream Totem with 5 health at the feet of the caster for 5 min that heals group members within 30 yards for 8 every 2 seconds.\nSell Price: 2 50" }
entries[5701] = { ["name"] = "Tablet of Sentry Totem", ["text"] = "Classes: Shaman\nRequires Level 14\nUse: Teaches Sentry Totem.\nSummons an immobile Sentry Totem with 100 health at your feet for 5 min that allows vision of nearby area and warns of enemies that attack it. Right-Click on buff to switch back and forth between totem sight and shaman sight.\nSell Price: 3 25" }
entries[5702] = { ["name"] = "Tablet of Agitating Totem II", ["text"] = "Classes: Shaman\nRequires Level 18\nUse: Teaches Agitating Totem (Rank 2).\nSummons a Stoneclaw Totem with [150 + floor(Stamina * 0.05)] health at the feet of the caster for 15 sec that taunts creatures within 8 yards to attack it. Enemies attacking the Stoneclaw Totem have a 50% chance to be stunned for 3 sec. Stoneclaw totem also protects all your totems, causing them to absorb 58 damage.\nSell Price: 6 25" }
entries[5703] = { ["name"] = "Tablet of Thunderclap", ["text"] = "Classes: Shaman\nRequires Level 20\nUse: Teaches Thunder Clap (Rank 1).\nBlasts nearby enemies increasing the time between their attacks by 10% for 10 sec and doing 15 damage to them. Damage increased by attack power. This ability causes additional threat.\nSell Price: 7 50" }
entries[5704] = { ["name"] = "Tablet of Water Breathing", ["text"] = "Classes: Shaman\nRequires Level 20\nUse: Teaches Water Breathing.\nAllows the target to breathe underwater for 10 min.\nSell Price: 7 50" }
